-- ============================================================
-- Data migration: wildlwdl_ngenzi → properties, plots, cars ONLY
-- ============================================================
-- Source: wildlwdl_ngenzi.sql
-- Counts: 1 property, 47 plots (ids 5–51), 5 cars (ids 2–6)
--
-- 1. Ensure tables exist (import backend/sql/schema.sql if needed).
-- 2. Import THIS file in phpMyAdmin on the target database.
-- 3. Copy /uploads/properties, /uploads/plots, /uploads/cars
--    from the old server into the new backend uploads folder
--    (image paths are relative like /uploads/...).
--
-- WARNING: DELETE clears existing rows in these three tables.
-- ============================================================

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- ---------- properties ----------
DELETE FROM `properties`;

-- ---------- plots ----------
DELETE FROM `plots`;

-- ---------- cars ----------
DELETE FROM `cars`;

-- Reset AUTO_INCREMENT
SET @m = (SELECT IFNULL(MAX(`id`), 0) + 1 FROM `properties`);
SET @q = CONCAT('ALTER TABLE `properties` AUTO_INCREMENT = ', @m);
PREPARE stmt FROM @q; EXECUTE stmt; DEALLOCATE PREPARE stmt;

SET @m = (SELECT IFNULL(MAX(`id`), 0) + 1 FROM `plots`);
SET @q = CONCAT('ALTER TABLE `plots` AUTO_INCREMENT = ', @m);
PREPARE stmt FROM @q; EXECUTE stmt; DEALLOCATE PREPARE stmt;

SET @m = (SELECT IFNULL(MAX(`id`), 0) + 1 FROM `cars`);
SET @q = CONCAT('ALTER TABLE `cars` AUTO_INCREMENT = ', @m);
PREPARE stmt FROM @q; EXECUTE stmt; DEALLOCATE PREPARE stmt;

SET FOREIGN_KEY_CHECKS = 1;
